def acyclic(edges):
    visiting = set()
    visited = set()

    def visit(node):
        if node in visiting:
            return False
        if node in visited:
            return True
        visiting.add(node)
        for target in edges.get(node, ()):
            if not visit(target):
                return False
        visiting.remove(node)
        visited.add(node)
        return True

    nodes = set(edges)
    for targets in edges.values():
        nodes.update(targets)
    return all(visit(node) for node in nodes)
